CREATE   PROCEDURE [synapse_ce].[usp_Insert_apuk_assessmentevent]
AS
BEGIN
	INSERT INTO [synapse_ce].[apuk_assessmentevent]
	(
		[apuk_applicationtype],
		[apuk_applicationtypeid],
		[apuk_applicationtypeid_entitytype],
		[apuk_applicationtypeidname],
		[apuk_assessmentapplicationwindowid],
		[apuk_assessmentapplicationwindowid_entitytype],
		[apuk_assessmentapplicationwindowidname],
		[apuk_assessmenteventid],
		[apuk_assessmentvenue],
		[apuk_assessmentvenue_entitytype],
		[apuk_assessmentvenuename],
		[apuk_dayfivedate],
		[apuk_dayfourdate],
		[apuk_dayonedate],
		[apuk_daysixdate],
		[apuk_daythreedate],
		[apuk_daytwodate],
		[apuk_electiondate],
		[apuk_firstchoicecompletedon],
		[apuk_firstchoicestartedon],
		[apuk_locationid],
		[apuk_locationid_entitytype],
		[apuk_locationidname],
		[apuk_name],
		[apuk_noofrooms1],
		[apuk_noofrooms2],
		[apuk_noofrooms3],
		[apuk_noofrooms4],
		[apuk_noofrooms5],
		[apuk_noofrooms6],
		[apuk_secondchoicecompletedon],
		[apuk_secondchoicestartedon],
		[apuk_thirdchoicecompletedon],
		[apuk_thirdchoicestartedon],
		[apuk_whatshappening],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[Id],
		[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[overriddencreatedon],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[timezoneruleversionnumber],
		[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[apuk_applicationtype],
		stg.[apuk_applicationtypeid],
		stg.[apuk_applicationtypeid_entitytype],
		stg.[apuk_applicationtypeidname],
		stg.[apuk_assessmentapplicationwindowid],
		stg.[apuk_assessmentapplicationwindowid_entitytype],
		stg.[apuk_assessmentapplicationwindowidname],
		stg.[apuk_assessmenteventid],
		stg.[apuk_assessmentvenue],
		stg.[apuk_assessmentvenue_entitytype],
		stg.[apuk_assessmentvenuename],
		stg.[apuk_dayfivedate],
		stg.[apuk_dayfourdate],
		stg.[apuk_dayonedate],
		stg.[apuk_daysixdate],
		stg.[apuk_daythreedate],
		stg.[apuk_daytwodate],
		stg.[apuk_electiondate],
		stg.[apuk_firstchoicecompletedon],
		stg.[apuk_firstchoicestartedon],
		stg.[apuk_locationid],
		stg.[apuk_locationid_entitytype],
		stg.[apuk_locationidname],
		stg.[apuk_name],
		stg.[apuk_noofrooms1],
		stg.[apuk_noofrooms2],
		stg.[apuk_noofrooms3],
		stg.[apuk_noofrooms4],
		stg.[apuk_noofrooms5],
		stg.[apuk_noofrooms6],
		stg.[apuk_secondchoicecompletedon],
		stg.[apuk_secondchoicestartedon],
		stg.[apuk_thirdchoicecompletedon],
		stg.[apuk_thirdchoicestartedon],
		stg.[apuk_whatshappening],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[Id],
		stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[overriddencreatedon],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[timezoneruleversionnumber],
		stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[apuk_assessmentevent] stg
		LEFT JOIN [synapse_ce].[apuk_assessmentevent] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
